module.exports = /*#__PURE__*/JSON.parse('{"hero":{"eyebrow":"About us","title":"We explore the heart of Europe, one day at a time.","subtitle":"RITA Tours &amp; Travels is an EU-registered travel studio based in the Netherlands. We craft immersive day journeys—starting right here in the Dutch and Benelux regions—connecting you with authentic food, deep local history, and a real person behind every itinerary.","image":"https://media.base44.com/images/public/6aec6c41ac98455faf00216e/bf1b14139_generated_defda7f7.png","imageAlt":"Lakeside villas and mountains on Lake Como at golden hour","stats":[{"value":"2026","label":"ESTABLISHED IN THE NETHERLANDS"},{"value":"50","label":"MAXIMUM GUESTS PER TOUR"},{"value":"100%","label":"LOCALLY CRAFTED EXPERIENCES"},{"value":"EU","label":"PROTECTED TRAVEL STANDARDS"}]},"story":{"eyebrow":"01 — Our story","title":"A notebook, a rail timetable and a stubborn idea.","paragraphs":["RITA began in 2014 with a notebook, a rail timetable and a belief that a good trip is mostly about what you leave out. Two planners in Amsterdam started booking slow weeks for friends who wanted Italy without the coach parties, the queue at the ticket desk or the sixth museum of the day.","Twelve years on we are a team of planners, guides and rail enthusiasts across five European countries. The method has not changed: fewer places, longer stays, and one named planner who answers your emails from the first idea to the last train home.","We do not resell fixed packages. Every journey in our catalogue started as a private itinerary that guests asked us to run again for others — which is why each one has been walked, tested and rewritten before it appears here."],"image":"https://media.base44.com/images/public/6aec6c41ac98455faf00216e/4ca6b020b_generated_215f6f69.png","imageAlt":"Terraced lemon groves above the Amalfi Coast","imageCaption":"Scouting the Path of the Gods route above Positano, spring 2025.","signature":"Rita Vermeer, founder","signatureNote":"Amsterdam, the Netherlands"},"heritage":{"eyebrow":"02 — EU heritage","title":"European by registration. Local by habit.","subtitle":"We are a Dutch-registered company working under EU consumer protection rules for package travel — and we build every route with the people who actually live on it.","items":[{"year":"2014","title":"Founded in Amsterdam","body":"Two planners, one office above a bike shop, and the first Amalfi week planned for six friends."},{"year":"2017","title":"Rail-first itineraries","body":"We stopped booking internal flights wherever a night train or a scenic line could do the job better."},{"year":"2021","title":"A local partner network","body":"Guides and family-run hotels in Italy, Greece, France, Switzerland, Austria and Spain began working with us season after season."},{"year":"2024","title":"The sustainability ledger","body":"Every journey now carries a rough footprint estimate and a written note on what we are doing to reduce it."},{"year":"2026","title":"Planner-led, still small","body":"Nine people, one shared inbox, and a deliberate cap on how many trips we accept each month."}],"note":"RITA Tours N Travels is registered in the Netherlands and sells package travel under EU Directive (EU) 2015/2302. Full company and financial-protection details are confirmed in every quotation."},"team":{"eyebrow":"03 — The team","title":"The people who answer your emails.","subtitle":"No call centre, no rotating account manager. These are the planners, guides and rail nerds who will actually build and support your journey.","members":[{"name":"Rita Vermeer","role":"Founder & Lead Planner","base":"Amsterdam, NL","focus":"Started RITA after a decade guiding in Italy. Still plans every Amalfi and Lake Como journey herself.","initials":"RV"},{"name":"Tomás Ferreira","role":"Alpine Journeys Planner","base":"Chamonix, FR","focus":"Routes, refuges and snow-line timing across the Alps. Knows which ridge walks work with a nine-year-old.","initials":"TF"},{"name":"Sofia Bellini","role":"Italy & Greece Specialist","base":"Bologna, IT","focus":"Ferries, family kitchens and the quiet side of the Aegean. Writes the food notes you receive before departure.","initials":"SB"},{"name":"Lukas Berger","role":"Guide & Route Checker","base":"Innsbruck, AT","focus":"Walks every new itinerary before it goes on sale, then guides the Dolomites hut-to-hut weeks in season.","initials":"LB"},{"name":"Amélie Rousseau","role":"Guest Care Lead","base":"Lyon, FR","focus":"The person on the phone when a train is cancelled. Keeps the 24-hour support line calm and useful.","initials":"AR"},{"name":"Núria Costa","role":"Sustainability & Rail","base":"Barcelona, ES","focus":"Compares every routing option by journey time and emissions, and keeps our carbon estimates honest.","initials":"NC"}]},"sustainability":{"eyebrow":"04 — Sustainability","title":"Travel beautifully. Travel with fewer kilometres.","subtitle":"We would rather send you to one region properly than six countries badly. These are the commitments we hold ourselves to on every journey we sell.","image":"https://media.base44.com/images/public/6aec6c41ac98455faf00216e/13d61b0b0_generated_f91fb656.png","imageAlt":"Dolomites limestone peaks above an alpine meadow","commitments":[{"metric":"68%","metricLabel":"of nights by rail","title":"Rail where it works","body":"Most of our 2025 journeys reached their stays by train rather than by air or hire car. Where a rail leg exists, we plan around it."},{"metric":"5.4","metricLabel":"nights per stop","title":"Longer stays","body":"An average of more than five nights in one place, so your money and your time stay in the region instead of moving every morning."},{"metric":"14","metricLabel":"local partners","title":"Local partners paid directly","body":"Guides, drivers and family-run houses are contracted directly, with no booking-platform margin taken out of their side."},{"metric":"100%","metricLabel":"estimates shown","title":"Honest carbon numbers","body":"Every journey shows an estimate of its footprint and the assumptions behind it. We publish the method — and we do not sell offsets."}],"note":"Figures are internal estimates compiled from transport type, group size and nights booked. They are an indication of impact, not a certified audit, and no carbon credits are sold."}}');

